import numpy as np

def solve():
    n = 10
    a = [1/i for i in range(1, n+1)]
    b = [1/(i+1) for i in range(1, n+1)]

    A = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            if i!= j:
                A[i, j] = a[i] * b[j]
            else:
                A[i, j] = 1 + a[i] * b[j]

    return np.linalg.det(A)

